def find_middle(s):
    if not isinstance(s, str):
        return -1

    digits = [int(c) for c in s if c.isdigit()]

    if not digits:
        return -1

    product = 1
    for d in digits:
        product *= d

    product_str = str(product)
    length = len(product_str)

    if length % 2 == 1:
        mid_index = length // 2
        return int(product_str[mid_index])
    else:
        mid_start = (length // 2) - 1
        mid_end = length // 2 + 1
        middle_part = product_str[mid_start:mid_end]
        return int(middle_part)
